messages.content:
Game edukasi Endless Runner "Konsumsi vs Modal Run" siap dimainkan: ambil barang sesuai target kategori, hindari peti kemas dan palet. Saya pakai tingkat Santai (speed 300, 5 nyawa) dengan rintangan lebih sempit sesuai tabel kelayakan.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "konsumsi-modal-run", title: "Konsumsi vs Modal Run", seed: "konsumsi-modal-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ekonomi Dasar",
    concept: "Perbedaan barang konsumsi dan barang modal berdasarkan cara pemakaiannya",
    objectives: [
      "Mengelompokkan barang sebagai konsumsi atau modal",
      "Membedakan barang mahal rumah tangga dari barang modal produksi"
    ],
    misconceptions: ["Semua benda mahal adalah barang modal"],
    mode: "category",
    categories: [
      { id: "konsumsi", label: "Barang Konsumsi", color: "#2F80ED" },
      { id: "modal",    label: "Barang Modal",    color: "#E5A100" }
    ],
    items: [
      { id: "beras",        label: "Beras",             category: "konsumsi", explain: "Bahan makanan pokok yang habis dikonsumsi keluarga." },
      { id: "sabun",        label: "Sabun mandi",       category: "konsumsi", explain: "Habis terpakai untuk kebutuhan kebersihan pribadi." },
      { id: "bensin-motor", label: "Bensin motor pribadi", category: "konsumsi", explain: "Bahan bakar kendaraan pribadi, bukan untuk produksi." },
      { id: "obat-batuk",   label: "Obat batuk",        category: "konsumsi", explain: "Dikonsumsi langsung untuk mengobati sakit." },
      { id: "kulkas-rumah", label: "Kulkas rumah",      category: "konsumsi", explain: "Mahal, tetapi dipakai menyimpan makanan keluarga sendiri." },
      { id: "mesin-jahit",  label: "Mesin jahit pabrik", category: "modal",   explain: "Dipakai memproduksi pakaian untuk dijual." },
      { id: "traktor",      label: "Traktor sawah",     category: "modal",    explain: "Alat untuk mengolah lahan menghasilkan panen." },
      { id: "oven-bakery",  label: "Oven bakery",       category: "modal",    explain: "Dipakai memanggang roti yang akan dijual." },
      { id: "bor-industri", label: "Bor industri",      category: "modal",    explain: "Alat produksi di bengkel dan pabrik." },
      { id: "etalase",      label: "Etalase toko",      category: "modal",    explain: "Dipakai memajang dan menjual dagangan." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "peti-kemas", w: 100, h: 44, weight: 3 },
      { type: "hazard", id: "palet-kayu", w: 90, h: 70, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```
